package dev.eugheist.ttmodern;
final class BedrockDisabledAudit {
 static void run(net.neoforged.neoforge.event.server.ServerStartedEvent event){var server=event.getServer();if(TinkererConfig.bedrockEnabled()||server.getLevel(BedrockPortal.DIMENSION)!=null||server.levelKeys().contains(BedrockPortal.DIMENSION))throw new IllegalStateException("disabled Bedrock dimension still loaded");if(server.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.LEVEL_STEM).containsKey(BedrockPortal.DIMENSION.location()))throw new IllegalStateException("disabled Bedrock stem still registered");if(server.overworld()==null||server.getLevel(net.minecraft.world.level.Level.NETHER)==null||server.getLevel(net.minecraft.world.level.Level.END)==null)throw new IllegalStateException("vanilla dimensions changed");System.out.println("TT BEDROCK CONFIG AUDIT: ALL PASS (actual bedrockDimensionID=0,no Bedrock level or stem including saved-world merge,vanilla dimensions retained)");}
}
